// ═══ PriorityQueue: min-heap ═══
PriorityQueue<Integer> pq = new PriorityQueue<>();  // min-heap (smallest first)
pq.offer(50000); pq.offer(10000); pq.offer(75000);

pq.peek();   // 10000 — smallest! O(1)
pq.poll();   // 10000 — removes smallest! O(log n)
pq.poll();   // 50000
pq.poll();   // 75000

// Max-heap:
PriorityQueue<Integer> maxPq = new PriorityQueue<>(Comparator.reverseOrder());
maxPq.offer(50000); maxPq.offer(10000); maxPq.offer(75000);
maxPq.poll(); // 75000 — LARGEST first!

// ═══ ITERATION IS NOT SORTED! ═══
PriorityQueue<Integer> pq2 = new PriorityQueue<>(List.of(30, 10, 20));
// Iterating pq2: might print 10, 30, 20 — NOT 10, 20, 30!
// Only pq2.peek() guarantees the minimum!

// ═══ SORTED ALTERNATIVES ═══
TreeSet<Integer> sorted = new TreeSet<>(List.of(30, 10, 20));
// Iteration: 10, 20, 30 — always sorted!
// But: no duplicates (it's a Set)!

List<Integer> sortedList = new ArrayList<>(List.of(30, 10, 20));
Collections.sort(sortedList);
// Iteration: 10, 20, 30 — sorted after explicit sort call
// Allows duplicates, but must re-sort after every add

// ═══ COMPARISON ═══
// Feature              PriorityQueue         TreeSet           Sorted ArrayList
// Get min/max          O(1) peek             O(log n) first()  O(1) get(0) after sort
// Add                  O(log n)              O(log n)          O(1) + re-sort O(n log n)
// Remove min           O(log n) poll         O(log n) pollFirst O(n) remove(0)
// Iteration sorted?    NO ❌                 YES ✅            YES (after sort) ✅
// Duplicates           YES ✅                NO ❌             YES ✅
// Use case             "Next most important"  "All sorted, unique" "All sorted"
