package com.bank.pq;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class PriorityQueueTest {

    record Trade(String id, BigDecimal amount) {}

    @Test
    void minHeap_smallestFirst() {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        pq.offer(50000); pq.offer(10000); pq.offer(75000);

        assertThat(pq.poll()).isEqualTo(10000);  // smallest!
        assertThat(pq.poll()).isEqualTo(50000);
        assertThat(pq.poll()).isEqualTo(75000);
    }

    @Test
    void maxHeap_largestFirst() {
        PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.reverseOrder());
        pq.offer(50000); pq.offer(10000); pq.offer(75000);

        assertThat(pq.poll()).isEqualTo(75000);  // largest!
    }

    @Test
    void customComparator_highestAmountFirst() {
        PriorityQueue<Trade> pq = new PriorityQueue<>(
            Comparator.comparing(Trade::amount).reversed());

        pq.offer(new Trade("T1", new BigDecimal("100000")));
        pq.offer(new Trade("T2", new BigDecimal("750000")));
        pq.offer(new Trade("T3", new BigDecimal("500000")));

        assertThat(pq.poll().id()).isEqualTo("T2");  // 750K — highest!
        assertThat(pq.poll().id()).isEqualTo("T3");  // 500K
    }

    @Test
    void iterationNotSorted() {
        PriorityQueue<Integer> pq = new PriorityQueue<>(List.of(30, 10, 20));
        List<Integer> iterated = new ArrayList<>(pq);  // iteration order!
        List<Integer> polled = new ArrayList<>();
        while (!pq.isEmpty()) polled.add(pq.poll());  // poll order!

        assertThat(polled).containsExactly(10, 20, 30);  // poll = sorted!
        // iterated may NOT be [10, 20, 30] — heap order ≠ sorted order!
    }

    @Test
    void allowsDuplicates() {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        pq.offer(100); pq.offer(100); pq.offer(100);
        assertThat(pq).hasSize(3);  // duplicates allowed!
    }
}
