class TradeScheduler {
    // max-heap by amount — HEAD = highest value trade
    private final PriorityQueue<Trade> queue =
        new PriorityQueue<>(Comparator.comparing(Trade::amount).reversed());

    void submit(Trade t){ queue.offer(t); }      // O(log n) sift-up
    Trade next()       { return queue.poll(); }  // O(log n) remove head
    Trade peek()       { return queue.peek(); }  // O(1) view head
    // NOTE: iterating queue is NOT sorted (heap array order)

    // Sorted report view — ALL elements ordered, dedup
    NavigableSet<Trade> dailyReport =
        new TreeSet<>(Comparator.comparing(Trade::tradeDate));
    SortedSet<Trade> forDate(LocalDate d){        // range query
        return dailyReport.subSet(first(d), last(d));
    }
    // PQ allows duplicate amounts; TreeSet collapses equal comparisons.
}
